import type { Layer } from "../studio-types";
import { channels } from "./types";
import { createSeededPlacementMarks, createRadialPlacementMarks, vertexInto } from "../../../../packages/javascript/examples/placement-marks/placement-marks.js";

function placements(p: any, l: Layer) {
  const q = l.params,
    model = q.radial
      ? createRadialPlacementMarks(Number(q.separation))
      : createSeededPlacementMarks(
          l.seed,
          Number(q.attempts),
          Number(q.minimum),
          Number(q.maximum),
          Number(q.separation),
        );
  const pt = new Float64Array(2),
    vertices = q.diamonds ? 4 : 64;
  p.noFill();
  p.strokeWeight(1);
  p.strokeCap(p.ROUND);
  p.strokeJoin(p.ROUND);
  for (let i = 0; i < model.placements.size; i++) {
    p.stroke(
      ...channels(
        l.palette[model.placements.sourceIndexAt(i) % l.palette.length],
      ),
    );
    p.beginShape();
    for (let v = 0; v < vertices; v++) {
      vertexInto(model.placements, i, v, Boolean(q.diamonds), pt);
      p.vertex(pt[0], pt[1]);
    }
    p.endShape(p.CLOSE);
  }
}

