      p.noStroke();
      fill(p, col, q.opacity);
      p.triangle(...a, ...b, ...c);
    } else {
      p.noStroke();
      fill(p, col, 210);
      const area =
          Math.abs(
            (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]),
          ) * 0.5,
        count = Math.min(800, Math.floor(area * q.grain)),
        points = seededTrianglePoints2D({
          seed: (l.seed + i) >>> 0,
          count,
          triangle: [a, b, c],
