    const points = model.regionAt(i);
    for (let j = 0; j < points.size; j++) {
      const pt = points.pointAt(j),
        col = pick(palette, i + j);
      if (q.strokes) {
        colour(p, col, 190);
        p.line(pt[0] - q.size, pt[1], pt[0] + q.size, pt[1]);
      } else {
        p.noStroke();
        fill(p, col, 200);
        p.circle(pt[0], pt[1], q.size);
      }
    }
  }
}

